(() => {
 const L=window.NEMO_LANDING,root=document.querySelector('#landing-view');let config=null,revision=0,dirty=false,saving=false;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const field=(label,key,value,max=160,area=false)=>'<label>'+label+(area?'<textarea':'<input type="text"')+' data-landing-field="'+key+'" maxlength="'+max+'"'+(area?'>'+esc(value)+'</textarea>':' value="'+esc(value)+'">')+'</label>';
 const tools=(group,i)=>'<div class="landing-row-tools"><button type="button" data-row="'+group+':'+i+':up" aria-label="항목 위로">↑</button><button type="button" data-row="'+group+':'+i+':down" aria-label="항목 아래로">↓</button><button type="button" data-row="'+group+':'+i+':remove" class="danger">삭제</button></div>';
 const add=(group,label)=>'<button type="button" class="secondary" data-add-landing="'+group+'">＋ '+label+'</button>';
 function render(){
  const open=new Set([...root.querySelectorAll('details[data-group][open]')].map(n=>n.dataset.group));
  const sections=[['marquee','전광판 문구',config.marquee],['domestic','국내 지도 · 후기',config.domestic],['overseas','해외 프로젝트',config.overseas]];
  root.innerHTML='<form id="landing-form"><div class="landing-save-bar"><div><strong>홈페이지 관리</strong><p>저장하면 홈페이지에 바로 반영됩니다.</p></div><button type="submit" class="primary">변경 내용 저장</button><a class="secondary" href="/" target="_blank" rel="noopener">홈페이지 확인 ↗</a></div><p id="landing-status" role="status">'+(dirty?'저장되지 않은 변경 사항':'저장된 내용')+'</p><p id="landing-error" class="error" role="alert"></p><section class="landing-settings-panel"><h2>후기 영역 제목과 프로젝트 수</h2><div class="landing-field-grid">'+field('작은 제목','reviewEyebrow',config.reviewEyebrow,80)+field('영역 제목','reviewTitle',config.reviewTitle,160,true)+field('전체 프로젝트 표시 이름','totalLabel',config.totalLabel,50)+field('전체 프로젝트 수 (예: 200+)','totalProjects',config.totalProjects,24)+field('해외 프로젝트 표시 이름','overseasLabel',config.overseasLabel,50)+field('해외 프로젝트 수 (예: 5+)','overseasProjects',config.overseasProjects,24)+field('지도 아래 출처 문구','dataSource',config.dataSource,80)+'</div></section>'+sections.map(([group,title,rows])=>'<details class="landing-settings-panel" data-group="'+group+'"'+(open.has(group)?' open':'')+'><summary>'+title+' <span>'+rows.length+'개</span></summary>'+(group==='domestic'?'<p class="field-hint">지역을 선택하면 핀 위치와 지도 이름이 자동으로 들어갑니다. 같은 지역은 핀 하나에 묶이고, 후기 개수와 넘기기 버튼이 표시됩니다.</p><div class="landing-map-picker"><button type="button" id="landing-map-select" aria-label="지도에서 가까운 지역 선택"><img src="/assets/south-korea.svg" alt="지역 선택용 대한민국 지도"></button><div><label>새 후기 지역<select id="landing-new-region">'+L.regions.map(r=>'<option value="'+r.id+'">'+r.label+'</option>').join('')+'</select></label><p id="landing-region-hint" class="field-hint">지도를 클릭하면 가까운 지역을 선택합니다. 지도 이름은 아래에서 바꿀 수 있습니다.</p>'+add('domestic','선택한 지역에 후기 추가')+'</div></div>':'')+'<div class="landing-rows">'+rows.map((r,i)=>{
   if(group==='marquee')return '<fieldset><legend>문구 '+(i+1)+'</legend>'+field('전광판 내용',group+':'+i+':text',r.text,300,true)+field('아래 분류 문구',group+':'+i+':label',r.label,60)+tools(group,i)+'</fieldset>';
   if(group==='overseas')return '<fieldset><legend>해외 프로젝트 '+(i+1)+'</legend><div class="landing-field-grid">'+field('국가 / 지역',group+':'+i+':country',r.country,60)+field('프로젝트 이름',group+':'+i+':title',r.title,160)+'</div>'+field('설명',group+':'+i+':description',r.description,600,true)+tools(group,i)+'</fieldset>';
   return '<details class="landing-review-row"><summary>'+esc((r.mapLabel||L.regions.find(x=>x.id===r.region)?.label)+' · '+(r.person||'새 후기'))+'</summary><div class="landing-field-grid"><label>지역<select data-landing-field="'+group+':'+i+':region">'+L.regions.map(x=>'<option value="'+x.id+'"'+(x.id===r.region?' selected':'')+'>'+x.label+'</option>').join('')+'</select></label>'+field('지도에 표시할 이름',group+':'+i+':mapLabel',r.mapLabel,30)+field('공간 종류',group+':'+i+':kind',r.kind,60)+field('표시 이름',group+':'+i+':person',r.person,60)+'</div>'+field('후기 내용',group+':'+i+':quote',r.quote,1000,true)+tools(group,i)+'</details>';
  }).join('')+'</div>'+(group==='domestic'?'':add(group,group==='marquee'?'전광판 문구 추가':'해외 프로젝트 추가'))+'</details>').join('')+'</form>';
 }
 function mark(){dirty=true;root.querySelector('#landing-status').textContent='저장되지 않은 변경 사항';}
 async function request(options){const response=await fetch('/api/admin/landing',{credentials:'same-origin',...options,headers:{'Content-Type':'application/json'}}),data=await response.json();if(!response.ok)throw Error(data.error||'불러오지 못했습니다.');return data;}
 async function open(){document.querySelector('#list-description').textContent='전광판 문구, 국내·해외 프로젝트, 지도 후기와 프로젝트 수를 관리하세요.';dirty=false;root.innerHTML='<p role="status">홈페이지 내용을 불러오는 중입니다.</p>';try{const state=await request();config=state.config;revision=state.revision;render();}catch(e){root.innerHTML='<p class="error" role="alert">'+esc(e.message)+'</p><button type="button" class="secondary" data-retry-landing>다시 불러오기</button>';}}
 root.addEventListener('input',e=>{const key=e.target.dataset.landingField;if(!key)return;const parts=key.split(':');if(parts.length===1)config[key]=e.target.value;else{const [group,i,field]=parts;config[group][+i][field]=e.target.value;if(field==='region'){const region=L.regions.find(x=>x.id===e.target.value);config[group][+i].mapLabel=region.label;root.querySelector('[data-landing-field="'+group+':'+i+':mapLabel"]').value=region.label;}}mark();});
 root.addEventListener('click',e=>{
  if(e.target.closest('[data-retry-landing]')){open();return;}
  const map=e.target.closest('#landing-map-select');if(map){const box=map.querySelector('img').getBoundingClientRect(),r=L.nearestRegion((e.clientX-box.left)/box.width*100,(e.clientY-box.top)/box.height*100);root.querySelector('#landing-new-region').value=r.id;root.querySelector('#landing-region-hint').textContent='선택한 지역: '+r.label+' · 아래 버튼으로 추가하세요.';return;}
  const adding=e.target.closest('[data-add-landing]');if(adding){const group=adding.dataset.addLanding,max={domestic:100,marquee:30,overseas:50}[group];if(config[group].length>=max){root.querySelector('#landing-error').textContent='이 항목은 최대 '+max+'개까지 등록할 수 있습니다.';return;}const id=crypto.randomUUID();if(group==='domestic'){const r=L.regions.find(x=>x.id===root.querySelector('#landing-new-region').value);config.domestic.push({id,region:r.id,mapLabel:r.label,kind:'',person:'',quote:''});}else config[group].push(group==='marquee'?{text:'',label:''}:{id,country:'',title:'',description:''});mark();render();if(group==='domestic')root.querySelector('.landing-review-row:last-child').open=true;return;}
  const tool=e.target.closest('[data-row]');if(!tool)return;const [group,raw,action]=tool.dataset.row.split(':'),i=+raw,rows=config[group];if(action==='remove'){if(!confirm('이 항목을 목록에서 삭제할까요? 저장하기 전에는 홈페이지에 반영되지 않습니다.'))return;rows.splice(i,1);}else{const next=i+(action==='up'?-1:1);if(next<0||next>=rows.length)return;[rows[i],rows[next]]=[rows[next],rows[i]];}mark();render();
 });
 root.addEventListener('submit',async e=>{e.preventDefault();if(saving)return;saving=true;const button=root.querySelector('[type="submit"]');button.disabled=true;root.querySelector('#landing-error').textContent='';try{const state=await request({method:'PUT',body:JSON.stringify({expectedRevision:revision,config})});revision=state.revision;dirty=false;root.querySelector('#landing-status').textContent='저장 완료 · 홈페이지에 반영했습니다.';}catch(error){root.querySelector('#landing-error').textContent=error.message;}finally{saving=false;button.disabled=false;}});
 window.NEMO_LANDING_ADMIN={open,isDirty:()=>dirty,discard:()=>{dirty=false;}};
})();
